import{_ as t,o as s,c as r,a5 as i}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-12-create-workspace/report3_spec.md","filePath":"feature/agency-workspace/3-4-12-create-workspace/report3_spec.md"}'),n={name:"feature/agency-workspace/3-4-12-create-workspace/report3_spec.md"};function a(o,e,l,c,g,p){return s(),r("div",null,[...e[0]||(e[0]=[i("<p><strong>3.4.12 Create Workspace</strong></p><p><strong>Function Trigger</strong></p><p>Begins when the Agency Owner submits the Create Workspace form with a Workspace name and the target Agency.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: The Agency OWNER only.</li><li><strong>Purpose</strong>: Creates a Workspace inside an Agency; the creator becomes its MANAGER by default, and members may optionally be assigned - including transferring the MANAGER role - at creation time.</li><li><strong>Interface</strong>: Create Workspace form - name input, Agency field, extended Workspace profile fields, and an optional member-assignment block.</li><li><strong>Data Processing</strong>: The system validates the request, creates the Workspace row, inserts the creator&#39;s membership in the same transaction, then applies any assignment entries - demoting the creator to CREATOR when the MANAGER role was transferred.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Create Workspace Screen:</p><ul><li>A single form screen scoped to one Agency.</li><li>Name input (required) and the target Agency (required).</li><li>Optional extended fields: industry, company size, website, phone, location, description, brand colour, logo icon, tagline, founded year, social links.</li><li>Optional member-assignment block letting the user pick Agency members and a role each (MANAGER / CREATOR / CLIENT).</li><li>A &quot;Create&quot; action; on success the user is taken into the new Workspace.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: name; agencyId.</li><li><strong>Input optional</strong>: industry, companySize, website, phone, location, description, brandColor, logoIcon, tagline, foundedYear, social links, assignMembers (list of {userId, role}).</li><li><strong>System data</strong>: the caller&#39;s authenticated identity; the Agency membership of the caller; default Workspace settings; the created Workspace identifier.</li><li><strong>Output</strong>: the created Workspace - id, name, agencyId, settings, industry, companySize, website, phone, location, description, branding fields, social links, createdAt.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-24</strong>: Creating a workspace inserts the creator as a workspace_members row with role MANAGER (or CREATOR when the MANAGER role is transferred via assignMembers), isActive=true.</li><li>If assignMembers names exactly one other user as MANAGER, the creator is automatically demoted to CREATOR - a Workspace has exactly one active MANAGER at any time.</li><li>The Workspace row and the creator&#39;s membership row are created in a single transaction; assignMembers entries are applied immediately afterwards.</li><li>name empty or agencyId missing -&gt; 400 VALIDATION_ERROR.</li><li>More than one MANAGER entry in assignMembers besides the creator -&gt; 409 MANAGER_ALREADY_ASSIGNED.</li><li><strong>BR-29</strong>: The caller must be an active member of the target Agency and must specifically hold the OWNER role, checked before the Workspace row is built; otherwise 403 NOT_AGENCY_OWNER.</li><li>An assignMembers entry whose user is not a member of that Agency -&gt; 403 NOT_AGENCY_MEMBER.</li><li>An assignMembers entry whose user record does not exist -&gt; USER_NOT_FOUND.</li><li>An assignMembers entry whose user already has an active membership in the new Workspace is skipped without error.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>name empty -&gt; Display: <strong>MSG02</strong>.</li><li>agencyId missing -&gt; 400 VALIDATION_ERROR.</li><li>industry must be a valid WorkspaceIndustry value; companySize must be a valid CompanySize value.</li><li>foundedYear, when supplied, must be a numeric year.</li><li>Every assignMembers role must be one of MANAGER / CREATOR / CLIENT - there is no workspace-level OWNER, OWNER exists only at Agency level.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>User opens the Create Workspace form inside an Agency and fills in the name, the Agency, and any optional fields.</li><li>System verifies the caller is an active member of that Agency and holds the OWNER role.</li><li>System creates the Workspace row with default settings and records the caller as its creator.</li><li>System inserts the creator&#39;s membership with role MANAGER - or CREATOR when the MANAGER role is being transferred.</li><li>System applies the assignMembers entries, inserting a membership row for each valid entry.</li><li>System returns the created Workspace and the user is taken into it; toast <strong>MSG31</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>1.a1: name empty -&gt; Display: <strong>MSG02</strong>. 1.a2: The user corrects the field and resubmits.</li><li>1.b1: agencyId missing -&gt; 400 VALIDATION_ERROR. 1.b2: The user selects an Agency and resubmits.</li><li>2.a1: Caller is not an active member of the target Agency, or is a member but not its OWNER -&gt; 403 NOT_AGENCY_OWNER, toast <strong>MSG39</strong>. 2.a2: The user is returned to the Agency list; the Workspace is not created.</li><li>5.a1: An assignMembers entry references a user outside the Agency -&gt; 403 NOT_AGENCY_MEMBER, toast <strong>MSG39</strong>. 5.a2: The user removes or corrects that entry and resubmits.</li><li>5.b1: An assignMembers entry references a user that does not exist -&gt; USER_NOT_FOUND, toast <strong>MSG38</strong>. 5.b2: The user removes or corrects that entry and resubmits.</li><li>5.c1: Two entries request MANAGER besides the creator -&gt; 409 MANAGER_ALREADY_ASSIGNED, toast <strong>MSG39</strong>. 5.c2: The user reduces the assignment to a single MANAGER and resubmits.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A Workspace row exists inside the Agency.</li><li>A membership row exists for the creator and for every valid assignMembers entry.</li><li>The new Workspace has exactly one active MANAGER.</li></ul>",14)])])}const h=t(n,[["render",a]]);export{d as __pageData,h as default};
